import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"支持的文件管理器","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/file-manager-support.md","filePath":"zh-CN/user-guide/file-manager-support.md","lastUpdated":1785993908000}'),o={name:"zh-CN/user-guide/file-manager-support.md"};function h(n,t,i,s,l,p){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="支持的文件管理器" tabindex="-1">支持的文件管理器 <a class="header-anchor" href="#支持的文件管理器" aria-label="Permalink to &quot;支持的文件管理器&quot;">​</a></h1><p>Lertaro 不只是能搜索——它还可以和你正在使用的文件管理器或对话框进行集成。根据目标窗口的不同，集成最多可以提供以下三种能力：</p><ul><li><strong>内嵌搜索</strong> —— Lertaro 的搜索框会直接嵌入目标窗口(也就是<a href="./getting-started.html#三种窗口">内嵌窗口</a>)，不用离开它就能搜索。</li><li><strong>快速导航</strong> —— 目标窗口会响应<a href="./hotkeys.html#快速导航鼠标">快速导航的鼠标触发方式</a>(双击/中键，或者内嵌窗口自带的图标)，弹出一个包含收藏夹、历史记录和快捷文件夹的级联菜单。</li><li><strong>活动路径检测</strong> —— Lertaro 能识别目标窗口当前打开的是哪个文件夹，从而把搜索范围限定在该文件夹内，并让复制路径这类基于相对路径的动作能正确解析。</li></ul><p>并不是每种集成都同时提供这三种能力——具体见下表。</p><h2 id="内置-无需额外安装" tabindex="-1">内置(无需额外安装) <a class="header-anchor" href="#内置-无需额外安装" aria-label="Permalink to &quot;内置(无需额外安装)&quot;">​</a></h2><p>以下几项都随 Lertaro 的核心扩展插件一起提供，不需要单独启用。</p><table tabindex="0"><thead><tr><th>目标</th><th>内嵌搜索</th><th>快速导航</th><th>活动路径检测</th></tr></thead><tbody><tr><td>Windows 文件资源管理器</td><td>支持</td><td>双击或中键</td><td>支持</td></tr><tr><td>现代打开/保存文件对话框</td><td>支持(这个对话框本身就是内嵌窗口)</td><td>中键，或左键点击内嵌窗口自带的图标</td><td>——</td></tr><tr><td>经典打开/保存文件对话框</td><td>支持</td><td>中键，或左键点击内嵌窗口自带的图标</td><td>——</td></tr><tr><td>经典浏览文件夹对话框</td><td>支持</td><td>中键，或左键点击内嵌窗口自带的图标</td><td>——</td></tr></tbody></table><p>活动路径检测对这几个对话框本身没有意义——一旦 Lertaro 已经嵌入对话框里，就不存在另一个&quot;其它窗口&quot;可供它检测并作为搜索范围了。</p><h2 id="可选插件-设置-→-插件" tabindex="-1">可选插件(设置 → 插件) <a class="header-anchor" href="#可选插件-设置-→-插件" aria-label="Permalink to &quot;可选插件(设置 → 插件)&quot;">​</a></h2><p>下面每一项都是独立的插件。在<a href="./settings/plugins.html">设置 → 插件</a>里安装/启用，然后在该插件自己的<strong>配置</strong>对话框里分别开关<strong>启用内嵌搜索</strong>和<strong>启用快速导航</strong>——两者默认都是开启的。</p><table tabindex="0"><thead><tr><th>目标</th><th>内嵌搜索</th><th>快速导航</th><th>活动路径检测</th></tr></thead><tbody><tr><td>Directory Opus</td><td>支持</td><td>在文件列表区域点击中键</td><td>支持</td></tr><tr><td>Files</td><td>支持</td><td>在文件列表区域点击中键</td><td>支持</td></tr><tr><td>One Commander</td><td>支持</td><td>在文件列表区域点击中键</td><td>支持</td></tr><tr><td>Total Commander</td><td>支持</td><td>在文件列表区域点击中键</td><td>支持</td></tr><tr><td>XYplorer</td><td>支持</td><td>在文件列表区域点击中键</td><td>支持</td></tr></tbody></table><p>这五款都是通过匹配运行中的进程来识别目标窗口的(其中 Directory Opus 和 Total Commander 还会通过它们各自公开文档记录的 <code>WM_COPYDATA</code> 远程控制接口通信，而不是直接抓取界面；Files 和 One Commander 没有提供远程控制协议，因此改用 UI Automation)。</p><h2 id="应用程序自带的对话框-可选插件" tabindex="-1">应用程序自带的对话框(可选插件) <a class="header-anchor" href="#应用程序自带的对话框-可选插件" aria-label="Permalink to &quot;应用程序自带的对话框(可选插件)&quot;">​</a></h2><p>这几项针对的是第三方应用程序里的某一个特定对话框——而不是整个应用程序，跟上面内置的那几个对话框是同一个思路。在<a href="./settings/plugins.html">设置 → 插件</a>里安装/启用，每个插件只有一个组件，直接在那里开关即可(没有单独的配置对话框，因为也没有别的东西需要切换)。</p><table tabindex="0"><thead><tr><th>目标</th><th>内嵌搜索</th><th>快速导航</th><th>活动路径检测</th></tr></thead><tbody><tr><td>WPS Office 的打开/保存对话框</td><td>支持</td><td>中键，或左键点击内嵌窗口自带的图标</td><td>——</td></tr><tr><td>WinRAR 的解压对话框</td><td>支持</td><td>中键，或左键点击内嵌窗口自带的图标</td><td>——</td></tr><tr><td>Bandizip 的解压对话框</td><td>支持</td><td>中键，或左键点击内嵌窗口自带的图标</td><td>——</td></tr><tr><td>Bandizip 的添加文件对话框</td><td>支持</td><td>中键，或左键点击内嵌窗口自带的图标</td><td>——</td></tr></tbody></table><p>识别靠的是控件结构而不是窗口标题，所以每款软件不管装的是哪种语言包都能正常工作。WPS 那一项覆盖文字、表格、演示和 PDF——它们用的是同一个对话框；WPS 不使用 Windows 自带的对话框，而是自绘了一个，这也正是它需要单独一个插件、而大多数程序被上面内置的那几项覆盖的原因。跟内置的那几个一样，活动路径检测在这里也没有意义——Lertaro 已经嵌入对话框本身了，不存在另一个&quot;其它窗口&quot;可供它检测并作为搜索范围。</p><hr><p>想为这里没有列出的文件管理器开发自己的集成？参见开发手册里的<a href="./../dev-guide/sdk/system-adapters.html">系统与对话框适配</a>参考文档。</p>',18)])])}const g=d(o,[["render",h]]);export{m as __pageData,g as default};
